 (w/'summary.json').write_text(json.dumps({'pin':inv['pin'],'upstream_rust_tests':54,'configurations':configs,'mutants_caught':caught,'admission':admission},indent=2)+'\n');print('network TCP client:',len(configs),'configurations;',len(caught),'mutants;',sum(x['functions'] for x in admission),'plans admitted')
